SELECT UTC_TIMESTAMP(3) AS observed_utc, DATABASE() AS db_schema;
SELECT version,description,installed_on,success FROM flyway_schema_history WHERE version IN ('209','210');
SELECT TABLE_NAME,COLUMN_NAME,DATA_TYPE FROM information_schema.columns WHERE table_schema=DATABASE() AND ((table_name='pull_task_group_execution' AND column_name LIKE 'profile_verified%') OR (table_name='pull_task_standard_setting' AND column_name LIKE '%interval%'));
SELECT a.id,a.tenant_id,a.owner_user_id,a.account_group_id,RIGHT(a.ws_phone,4) phone_tail,a.protocol_id,a.deleted_at,s.account_state,s.login_state,s.risk_status,s.risk_end_time,s.cooldown_until,s.mute_status,s.pulling_restriction_until,s.restriction_reason_code,s.state_source,s.last_state_sync_time,s.updated_at FROM account a LEFT JOIN account_state s ON s.account_id=a.id AND s.tenant_id=a.tenant_id WHERE a.id IN(999,1038,821) OR a.account_group_id IN(658,659,664);
SELECT id,tenant_id,owner_user_id,name,remark,marketing_occupancy_type,marketing_occupancy_task_id,deleted_at FROM account_group WHERE id IN(658,659,664);
SELECT table_name,column_name FROM information_schema.columns WHERE table_schema=DATABASE() AND ((column_name IN('account_id','builder_account_id','creator_account_id','puller_account_id','manager_account_id','released_at','status','task_status','state','account_group_id','protocol_id','base_url')) OR (table_name LIKE '%protocol%')) ORDER BY table_name,ordinal_position;
